/*
 * Additional generation-level vehicles for the dealership catalogue.
 *
 * Every entry is a real production car (or an iconic classic). A car only reaches the app when the Sketchfab
 * search below returns at least one real, licensed, embeddable 3D model whose title names it; wheels and aero
 * kits are attached only where a Dubai supplier lists them for that exact car (same rules as vehicles.mjs).
 *
 * e(make, model, generation, from, to, body, sketchfabQuery, titleKey, extras)
 *   titleKey  regex source the model title must match (case-insensitive)
 *   extras    { fuel: 'E' | 'H', m: part-title regex, prefer, not, ank }
 */
import { VEHICLES } from './vehicles.mjs';

const rx = (s, f = 'i') => new RegExp(s, f);
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const COUNTRY = {
  'Mercedes-Benz': 'Germany', BMW: 'Germany', Audi: 'Germany', Porsche: 'Germany', Volkswagen: 'Germany', Mini: 'United Kingdom', Cupra: 'Spain',
  Lamborghini: 'Italy', Ferrari: 'Italy', Maserati: 'Italy', 'Alfa Romeo': 'Italy', Lancia: 'Italy', Pagani: 'Italy', Fiat: 'Italy', Abarth: 'Italy', 'De Tomaso': 'Italy',
  McLaren: 'United Kingdom', Bentley: 'United Kingdom', 'Rolls-Royce': 'United Kingdom', 'Aston Martin': 'United Kingdom', Lotus: 'United Kingdom', Jaguar: 'United Kingdom',
  'Land Rover': 'United Kingdom', Ariel: 'United Kingdom', Caterham: 'United Kingdom', Noble: 'United Kingdom', Morgan: 'United Kingdom',
  Bugatti: 'France', Renault: 'France', Alpine: 'France', Peugeot: 'France', 'Citroën': 'France',
  Koenigsegg: 'Sweden', Volvo: 'Sweden', Polestar: 'Sweden', Rimac: 'Croatia', Spyker: 'Netherlands', Zenvo: 'Denmark',
  Toyota: 'Japan', Lexus: 'Japan', Nissan: 'Japan', Infiniti: 'Japan', Honda: 'Japan', Acura: 'Japan', Mazda: 'Japan', Mitsubishi: 'Japan', Subaru: 'Japan',
  Hyundai: 'South Korea', Genesis: 'South Korea', Kia: 'South Korea',
  Ford: 'USA', Chevrolet: 'USA', Dodge: 'USA', Cadillac: 'USA', GMC: 'USA', Jeep: 'USA', Tesla: 'USA', Rivian: 'USA', Lucid: 'USA', Hummer: 'USA', Pontiac: 'USA',
  Plymouth: 'USA', Buick: 'USA', Shelby: 'USA', Hennessey: 'USA', SSC: 'USA', Saleen: 'USA', DeLorean: 'USA', Czinger: 'USA', Ram: 'USA',
  BYD: 'China', NIO: 'China', Zeekr: 'China', Xiaomi: 'China', Hongqi: 'China', Xpeng: 'China', 'W Motors': 'UAE'
};

const PART_MAKE = { 'Mercedes-Benz': 'MERCEDES', 'Alfa Romeo': 'ALFA', 'Land Rover': 'LAND ROVER', 'Aston Martin': 'ASTON', 'Rolls-Royce': 'ROLLS-ROYCE', Volkswagen: 'VOLKSWAGEN|VW', Chevrolet: 'CHEVROLET' };
const slug = (s) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

function e(make, model, gen, from, to, body, q, key, x = {}) {
  const id = slug(`${make}-${model}-${gen}`).replace(/-+$/, '');
  const makePart = PART_MAKE[make] || make.toUpperCase();
  const token = x.m || esc(model.split(/[\s/(]/)[0].toUpperCase());
  return {
    id, make, model, gen, from, to, body, country: COUNTRY[make] || '', fuel: x.fuel || 'G',
    match: [rx(`(${makePart}).*\\b${token}\\b`)],
    ank: { make, rx: rx(x.ank || esc(model.split(/[\s/(]/)[0])), from, to: to || 2100 },
    sf: { q, rx: rx(key), prefer: x.prefer ? rx(x.prefer) : undefined, not: x.not ? rx(x.not) : undefined, noMake: x.noMake }
  };
}

