/* Drop anything that duplicates a curated vehicle (same make + model + generation slug) and de-duplicate ids. */
const have = new Set(VEHICLES.map((v) => v.id));
const seen = new Set();
export const EXTRA_UNIQUE = EXTRA.filter((v) => {
  let id = v.id;
  let n = 2;
  while (have.has(id) || seen.has(id)) id = `${v.id}-${n++}`;
  v.id = id;
  seen.add(id);
  return true;
});
